 const STORE='fitable.movement.demo.v2',LEGACY='fitable.movement.demo.v1',UISTORE='fitable.movement.ui.v2',MALL='https://fitablekorea.com',today=C.dateKey,uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
