 const S={mode:'guest',tab:'today',session:{authenticated:false,auth_configured:false},demo:null,workouts:[],records:[],registrations:[],challenge:null,busy:false,error:'',storageOK:true,ui:{goal:'first_pullup',capability:'hang',exercise_id:'hang',assistance:'none',grip:'overhand',band_note:'',planned_sets:2,rest_seconds:60,target:'10',plan_origin:'recommended',plan_level:null,plan_version:3,plan_workout_id:null,guide_step:0,settings_open:false,performed_on:today(),active_id:null,timer:null,drafts:{},history:'all',muscle:'back'},pending:{},bootError:false,level:null};
