 const LEVELSTORE='fitable.program.level.v1',P=globalThis.FitableLevels||{levels:[],sources:{},frequency:{text:'',basis:[]},disclaimer:'',advance_rule:'',advance_basis:[],common_stop:[],common_stop_basis:[]},LV=P.levels;
