 function blockedByActive(){const ongoing=active();if(!ongoing)return false;S.tab='today';S.ui.active_id=ongoing.id;persistUI();render();scrollTo(0,0);notify('하던 운동을 먼저 마친 뒤 단계를 바꿀 수 있어요.');return true;}
